package com.markethub.identity.security;
import com.markethub.identity.domain.UserRole; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
class JwtServiceTest { private final JwtService jwt=new JwtService("0123456789abcdef0123456789abcdef","markethub-test",900); @Test void issuesVerifiableTokenWithSubjectAndEmail(){UUID id=UUID.randomUUID();var p=new MarketHubPrincipal(id,"customer@example.com","hash",UserRole.CUSTOMER,true);String token=jwt.issueAccessToken(p);assertEquals(id,jwt.subject(token));assertEquals("customer@example.com",jwt.email(token));assertEquals(900,jwt.accessTtlSeconds());} @Test void rejectsShortSecret(){assertThrows(IllegalStateException.class,()->new JwtService("too-short","markethub",900));} }